              opts:["Delhi / दिल्ली","Haryana / हरियाणा","Bihar / बिहार","Uttarakhand / उत्तराखण्ड","None of the above / उपर्युक्त में से कोई नहीं"],
              ans:1,
              exp:"Uttar Pradesh का शामली जिले की सीमा 'हरियाणा' राज्य से लगती है। हरियाणा राज्य से UP के कुल 6 जिलों की सीमाएँ लगती हैं — सहारनपुर, शामली, बागपत, गौतमबुद्ध नगर, अलीगढ़ और मथुरा।",
              exam:"UPSSSC Homeopathic Pharmacist 02/02/2025",
