              exp:"महोबा जिला उत्तर प्रदेश राज्य में बुन्देलखण्ड क्षेत्र में स्थित है। यह उत्तर प्रदेश और मध्य प्रदेश की सीमा पर स्थित है। महोबा जिला 11 फरवरी 1995 को हमीरपुर जिले से अलग करके बनाया गया था।",
