let _pyqPFilter = 'all';

function pyqRenderPaperCards() {
    const el = document.getElementById('pyqPaperCards');
    if (!el) return;
    const papers = _pyqPFilter === 'all' ? PYQ_PAPERS : PYQ_PAPERS.filter(p => p.exam === _pyqPFilter);
    el.innerHTML = papers.map(p => {
        let scoreHtml = '';
        try {
            const s = JSON.parse(localStorage.getItem('pyqp_' + p.id));
            if (s !== null) {
                const pct = Math.round((s / p.questions.length) * 100);
                const c = pct >= 80 ? '#059669' : pct >= 50 ? '#d97706' : '#dc2626';
                scoreHtml = `<span style="font-size:10px;font-weight:800;padding:2px 8px;border-radius:8px;background:${c}22;color:${c};border:1px solid ${c}44">${s}/${p.questions.length} • ${pct}%</span>`;
            }
        } catch(e) {}
        return `<div onclick="pyqOpenPaper('${p.id}')" style="background:var(--bg-card);border:1.5px solid var(--border);border-radius:14px;overflow:hidden;cursor:pointer;box-shadow:var(--shadow-sm);transition:border-color 0.2s" onmouseenter="this.style.borderColor='var(--accent-purple)'" onmouseleave="this.style.borderColor='var(--border)'">
            <div style="background:${p.color};padding:12px 14px;display:flex;align-items:center;gap:10px">
                <span style="font-size:22px">${p.icon}</span>
                <div style="flex:1">
                    <div style="font-size:13px;font-weight:800;color:#fff">${p.title}</div>
                    <div style="font-size:10px;color:rgba(255,255,255,0.65);margin-top:1px">${p.subject}</div>
                </div>
                <div style="text-align:right">
                    <div style="font-size:9px;font-weight:800;color:rgba(255,255,255,0.5);text-transform:uppercase">${p.exam}</div>
                    <div style="font-size:17px;font-weight:900;color:#fff">${p.year}</div>
                </div>
            </div>
            <div style="padding:10px 14px;display:flex;align-items:center;justify-content:space-between">
                <div style="display:flex;align-items:center;gap:8px">
                    <span style="font-size:11px;font-weight:700;color:var(--text-muted)">❓ ${p.questions.length} Questions</span>
                    ${scoreHtml}
                </div>
                <button style="padding:6px 14px;background:var(--accent-purple);border:none;border-radius:8px;font-size:11px;font-weight:700;color:#fff;cursor:pointer;font-family:inherit">▶ Start</button>
            </div>
        </div>`;
    }).join('');
}

function pyqFilterExam(exam, btn) {
    _pyqPFilter = exam;
    document.querySelectorAll('.pyq-exam-pill').forEach(b => {
        b.style.background = 'var(--bg-hover)'; b.style.color = 'var(--text-secondary)'; b.style.borderColor = 'var(--border)';
    });
    if (btn) { btn.style.background = 'var(--accent-purple)'; btn.style.color = '#fff'; btn.style.borderColor = 'var(--accent-purple)'; }
    pyqRenderPaperCards();
}

function pyqOpenPaper(id) {
    const paper = PYQ_PAPERS.find(p => p.id === id);
    if (!paper) return;
    // Map PYQ questions to the format _startCustomQuiz expects
    const pool = paper.questions.map(q => ({
        q:    q.q,
        hi:   q.hi || '',
        opts: q.opts,
        ans:  q.ans,
        exp:  q.exp || '',
        exam: paper.exam + ' ' + paper.year,
        ch:   0,
        diff: 'medium'
    }));
    const label = paper.icon + ' ' + paper.title + ' — ' + paper.subject;
    if (typeof _startCustomQuiz === 'function') {
        _startCustomQuiz(pool, label);
    }
}
